-- Contract fixture for isolated PostgreSQL security/transaction tests.
-- This is NOT a substitute for a production schema dump.
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql STABLE AS $$ SELECT current_setting('request.jwt.claim.role',true) $$;
GRANT USAGE ON SCHEMA public,auth TO anon,authenticated,service_role;
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),asaas_subscription_id text,plano_id uuid,status_assinatura text,proxima_cobranca date);
CREATE TABLE planos(id uuid PRIMARY KEY,recursos jsonb);
CREATE TABLE organization_settings(organization_id uuid PRIMARY KEY,modulos_ativos jsonb);
CREATE TABLE public_users(id uuid PRIMARY KEY,organization_id uuid,cargo text,cargos text[] DEFAULT '{}',ativo boolean,nome text,full_name text,telefone text,avatar_url text,primeiro_acesso boolean,last_seen timestamptz,updated_at timestamptz,custom_permissions jsonb);
CREATE TABLE clientes(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id uuid,user_id uuid);
CREATE TABLE lojas(id uuid PRIMARY KEY,organization_id uuid,nome text);
CREATE TABLE produtos(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id uuid,nome text,fornecedor_id bigint,quantidade_estoque integer,estoque_cd integer,estoque_mostruario_centro integer);
CREATE TABLE produto_variantes(id uuid PRIMARY KEY,organization_id uuid,produto_id bigint);
CREATE TABLE estoque(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid,variante_id uuid,loja_id uuid,quantidade integer DEFAULT 0,UNIQUE(variante_id,loja_id));
CREATE TABLE estoque_loja(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text,quantidade integer,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE vendas(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id uuid,cliente_id bigint,itens jsonb,loja text,loja_id uuid,cliente_nome text,numero_pedido text,status text,nfe_aprovada boolean,nfe_emitida boolean,nfe_status text,valor_total numeric,valor_pago numeric,valor_restante numeric,status_pagamento text,data_pagamento timestamptz);
CREATE TABLE entregas(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,venda_id bigint,organization_id uuid,pagamento_confirmado boolean,data_pagamento timestamptz);
CREATE TABLE tokens_gerenciais(id uuid PRIMARY KEY,organization_id uuid,usos_realizados integer,usado_em timestamptz,ativo boolean,tipo_token text,permissao text,expira_em timestamptz,max_usos integer);
CREATE TABLE role_permissions(id text PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid,cargo text,permissions jsonb DEFAULT '[]');
CREATE TABLE configuracoes_sistema(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id uuid,chave text,valor text);
CREATE TABLE lancamentos_financeiros(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id uuid,descricao text,valor numeric,tipo text,categoria text,data_lancamento date,status text,forma_pagamento text,venda_id bigint,numero_pedido text,data_vencimento date,origem text,fornecedor_nome text,deleted_at timestamptz,recorrente boolean DEFAULT false,origem_tipo text,origem_ref text,categoria_id bigint);
CREATE TABLE organization_nfe_configs(organization_id uuid PRIMARY KEY,ultimo_numero_nfe integer);
CREATE TABLE stone_config(id uuid PRIMARY KEY);
CREATE TABLE payment_links(id uuid PRIMARY KEY,venda_id bigint);
CREATE TABLE cobrancas_pix(id uuid PRIMARY KEY,organization_id uuid,venda_id bigint,entrega_id bigint,stone_txid text,valor numeric,status text,valor_pago numeric,data_pagamento timestamptz,webhook_recebido boolean,webhook_data jsonb,numero_pedido text);
CREATE TABLE compras_ordens(id uuid PRIMARY KEY,organization_id uuid,numero_pedido text,status text,metadata jsonb,fornecedor_id bigint,fornecedor_nome text,valor_total numeric,data_pedido date,prazo_pagamento integer,updated_at timestamptz);
CREATE TABLE compras_oc_itens(id uuid PRIMARY KEY,organization_id uuid,ordem_compra_id uuid,produto_id bigint,variante_id uuid,quantidade_recebida integer,quantidade_pedida integer,status_recebimento text,preco_unitario numeric);
CREATE TABLE compras_recebimentos_historico(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid,tenant_id uuid,ordem_compra_id uuid,numero_oc text,numero_nfe text,observacoes text,recebido_por uuid);
CREATE TABLE compras_recebimentos_itens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recebimento_id uuid,oc_item_id uuid,quantidade_recebida integer,preco_unitario numeric,observacao_item text);
CREATE TABLE movimentacoes_estoque(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid,produto_id bigint,evento_tipo text,modulo_origem text,quantidade integer,referencia_id uuid,referencia_numero text,usuario_id uuid);
CREATE TABLE historico_precos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid,produto_id bigint,produto_nome text,fornecedor_id bigint,fornecedor_nome text,ordem_compra_id uuid,numero_oc text,tipo text,motivo text,preco_antigo numeric,preco_novo numeric,delta_percentual numeric,created_at timestamptz DEFAULT now());
CREATE TABLE solicitacoes_encomenda(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid,venda_id bigint,produto_id bigint,produto_nome text,fornecedor_id bigint,quantidade integer,cliente_nome text,numero_pedido text,loja text,loja_id uuid,vendedor_id uuid,status text,ordem_id uuid,observacoes text);
GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated,service_role;
GRANT SELECT ON clientes TO anon;
ALTER TABLE clientes ENABLE ROW LEVEL SECURITY;
CREATE POLICY select_clientes_anon ON clientes FOR SELECT TO anon USING(true);
CREATE POLICY all_clientes ON clientes FOR ALL TO authenticated USING(true) WITH CHECK(true);
ALTER TABLE public_users ENABLE ROW LEVEL SECURITY;
CREATE POLICY legacy_users ON public_users FOR ALL TO authenticated USING(true) WITH CHECK(true);

CREATE FUNCTION public.get_user_org_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT organization_id FROM public.public_users WHERE id = auth.uid() $$;
CREATE TABLE categorias_financeiras(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id uuid DEFAULT public.get_user_org_id(),nome text,tipo text,cor text);
GRANT ALL ON categorias_financeiras TO authenticated,service_role;
